SELECT (DATE_TRUNC('HOUR', "LOAD_HOUR")) AS "TIME_BUCKET", SUM(QUERY_COUNT) AS "WH_QUERY_COUNT" FROM (SELECT "WAREHOUSE_NAME" AS WAREHOUSE_NAME, (DATE_TRUNC('HOUR', (TRY_CAST("START_TIME" AS TIMESTAMP)))) AS LOAD_HOUR, ("_ACCOUNT") AS ACCOUNT_NAME /* The account these rows came from (see the ACCOUNT_OF shim). Grouped on, */ /* so two accounts running a warehouse of the same name in the same hour */ /* stay two rows rather than one merged average. */, COUNT(*) AS QUERY_COUNT, SUM("QUEUED_OVERLOAD_TIME") AS QUEUED_OVERLOAD_MS, SUM("QUEUED_PROVISIONING_TIME") AS QUEUED_PROVISIONING_MS, SUM("TOTAL_ELAPSED_TIME") AS ELAPSED_MS, SUM("EXECUTION_TIME") AS EXECUTION_MS FROM query_history GROUP BY 1, 2, 3) AS base GROUP BY (DATE_TRUNC('HOUR', "LOAD_HOUR")) ORDER BY "WH_QUERY_COUNT" DESC, "TIME_BUCKET" LIMIT 100
